// Procesar datos de viaje del usuario
const travelData = $input.first().json;

// Validar datos requeridos
const requiredFields = ['origin', 'destination', 'departure_date', 'return_date', 'travelers'];
const missingFields = requiredFields.filter(field => !travelData[field]);

if (missingFields.length > 0) {
  throw new Error(`Campos requeridos faltantes: ${missingFields.join(', ')}`);
}

// Calcular duración del viaje
const departure = new Date(travelData.departure_date);
const returnDate = new Date(travelData.return_date);
const tripDuration = Math.ceil((returnDate - departure) / (1000 * 60 * 60 * 24));

// Determinar temporada y precios esperados
const month = departure.getMonth();
let season = 'low';
let priceMultiplier = 1.0;

if ([5, 6, 7, 11, 12].includes(month)) { // Junio, Julio, Agosto, Noviembre, Diciembre
  season = 'high';
  priceMultiplier = 1.4;
} else if ([3, 4, 8, 9].includes(month)) { // Abril, Mayo, Septiembre, Octubre
  season = 'medium';
  priceMultiplier = 1.2;
}

// Generar ID único de búsqueda
const searchId = `travel_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

return [{
  // Datos originales del usuario
  ...travelData,

  // Métricas calculadas
  trip_duration: tripDuration,
  season: season,
  price_multiplier: priceMultiplier,

  // Metadata
  search_id: searchId,
  processed_at: new Date().toISOString(),
  user_id: travelData.user_id || `user_${Math.random().toString(36).substr(2, 9)}`,

  // Configuración de APIs
  currency: travelData.currency || 'USD',
  locale: travelData.locale || 'en-US',

  // Rangos de fechas para búsqueda flexible
  flexible_dates: {
    departure_min: new Date(departure.getTime() - 2 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    departure_max: new Date(departure.getTime() + 2 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    return_min: new Date(returnDate.getTime() - 2 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    return_max: new Date(returnDate.getTime() + 2 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]
  }
}];

// Procesar resultados de IA y generar recomendaciones
const aiRecommendation = $input.first().json;
const flightData = $node['Skyscanner Flights'].json;
const hotelData = $node['Booking.com Hotels'].json;
const userData = $node['Process Travel Data'].json;

// Extraer mejores ofertas
const bestFlight = aiRecommendation.best_flight || {};
const bestHotel = aiRecommendation.best_hotel || {};
const alternativeOptions = aiRecommendation.alternatives || [];

// Construir enlaces de afiliado
const flightAffiliateLink = `https://www.skyscanner.net/transport/flights/${userData.origin}/${userData.destination}/${userData.departure_date}/${userData.return_date}/?adults=${userData.travelers}&affiliate=${$env.SKYSCANNER_AFFILIATE_ID}`;

const hotelAffiliateLink = `https://www.booking.com/searchresults.html?checkin=${userData.departure_date}&checkout=${userData.return_date}&selected_currency=${userData.currency}&ss=${bestHotel.hotel_name || userData.destination}&affiliate=${$env.BOOKING_AFFILIATE_ID}`;

// Calcular ahorros y métricas
const totalCost = (bestFlight.price || 0) + (bestHotel.price || 0);
const averageCost = aiRecommendation.market_average || totalCost * 1.2;
const savings = averageCost - totalCost;
const savingsPercentage = ((savings / averageCost) * 100).toFixed(1);

// Generar itinerario
const itinerary = {
  day_by_day: generateItinerary(userData, bestHotel, aiRecommendation.recommended_activities),
  total_cost: totalCost,
  cost_breakdown: {
    flights: bestFlight.price,
    hotel: bestHotel.price,
    activities: aiRecommendation.estimated_activities_cost || 50,
    food: aiRecommendation.estimated_food_cost || 100
  }
};

// Generar alertas de precio
const priceAlerts = [];
if (savingsPercentage > 15) {
  priceAlerts.push({
    type: 'great_deal',
    message: `¡Oferta excepcional! Estás ahorrando ${savingsPercentage}%`,
    priority: 'high'
  });
}

if (userData.budget && totalCost > userData.budget) {
  priceAlerts.push({
    type: 'over_budget',
    message: `El viaje excede tu presupuesto por $${totalCost - userData.budget}`,
    priority: 'medium'
  });
}

return [{
  // Datos del usuario
  ...userData,

  // Mejores ofertas
  best_flight: {
    ...bestFlight,
    affiliate_link: flightAffiliateLink
  },
  best_hotel: {
    ...bestHotel,
    affiliate_link: hotelAffiliateLink
  },

  // Alternativas
  alternative_options: alternativeOptions,

  // Análisis financiero
  total_cost: totalCost,
  market_average: averageCost,
  total_savings: savings,
  savings_percentage: savingsPercentage,

  // Itinerario
  itinerary: itinerary,

  // Alertas
  price_alerts: priceAlerts,

  // Recomendaciones de IA
  ai_recommendations: aiRecommendation.recommendations || [],
  confidence_score: aiRecommendation.confidence_score || 0.8,

  // Timestamps
  search_completed_at: new Date().toISOString(),
  price_valid_until: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
}];

// Funciones auxiliares
function generateItinerary(userData, hotel, activities) {
  const itinerary = [];
  const duration = userData.trip_duration;

  for (let i = 0; i < duration; i++) {
    const day = {
      day: i + 1,
      date: new Date(new Date(userData.departure_date).getTime() + i * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
      activities: []
    };

    // Día 1: Llegada
    if (i === 0) {
      day.activities = [
        'Llegada al aeropuerto',
        'Check-in en el hotel',
        'Exploración del área local',
        'Cena de bienvenida'
      ];
    }
    // Día último: Salida
    else if (i === duration - 1) {
      day.activities = [
        'Desayuno de despedida',
        'Check-out del hotel',
        'Últimas compras de recuerdos',
        'Traslado al aeropuerto'
      ];
    }
    // Días intermedios
    else {
      const availableActivities = activities || ['Tour cultural', 'Gastronomía local', 'Naturaleza', 'Compras'];
      day.activities = [
        'Desayuno en el hotel',
        availableActivities[i % availableActivities.length],
        'Tiempo libre',
        'Cena en restaurante local'
      ];
    }

    itinerary.push(day);
  }

  return itinerary;
}

